<section class="ho-driver-order-details__section ho-driver-order-details__section--timeline" aria-labelledby="timeline-title"><h2 id="timeline-title" class="ho-driver-order-details__section-title">Delivery timeline</h2><div class="ho-driver-order-details__card ho-driver-order-details__timeline">
